), actual AS MATERIALIZED (
 SELECT r.relname AS table_name,c.conname AS constraint_name,c.convalidated,
  encode(sha256(convert_to(pg_get_constraintdef(c.oid,false),'UTF8')),'hex') AS definition_sha256
 FROM pg_catalog.pg_constraint c JOIN pg_catalog.pg_class r ON r.oid=c.conrelid
 JOIN pg_catalog.pg_namespace n ON n.oid=r.relnamespace
 WHERE n.nspname='api_next' AND c.contype='c' AND r.relname IN(SELECT table_name FROM tables)
)
SELECT t.table_name,
 (SELECT count(*) FROM expected e WHERE e.table_name=t.table_name) AS expected_check_count,
 (SELECT count(*) FROM actual a WHERE a.table_name=t.table_name) AS actual_check_count,
 (SELECT count(*) FROM expected e LEFT JOIN actual a USING(table_name,constraint_name)
  WHERE e.table_name=t.table_name AND (a.constraint_name IS NULL OR a.definition_sha256<>e.definition_sha256)) AS missing_or_changed_checks,
 (SELECT count(*) FROM actual a LEFT JOIN expected e USING(table_name,constraint_name)
  WHERE a.table_name=t.table_name AND e.constraint_name IS NULL) AS unexpected_checks,
 (SELECT count(*) FROM actual a WHERE a.table_name=t.table_name AND NOT a.convalidated) AS unvalidated_checks,
 (to_regclass('api_next.'||quote_ident(t.table_name)) IS NULL)::integer AS missing_table
FROM tables t ORDER BY t.table_name;
